void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;  // Reduce threshold more aggressively to trigger rephase more often
    rephase_limit += 4096;  // Increase limit moderately to allow more rephases but not too many
    // During rephase, update saved phases based on current trail values and local best
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            saved[i] = value[i];  // Prefer current assignment
        } else if (rand() % 100 < 30) {
            saved[i] = local_best[i];  // Sometimes use local best
        } else {
            saved[i] = rand() % 2 ? 1 : -1;  // Otherwise randomize
        }
    }
}
